public class AlbumTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Album album = new Album();
        check("trackCount of an empty album", 0, album.trackCount());
        check("totalSeconds of an empty album", 0, album.totalSeconds());
        check("longestTrack of an empty album", null, album.longestTrack());
        album.add(new Track("Intro", 90));
        album.add(new Track("Anthem", 245));
        album.add(new Track("Outro", 120));
        check("trackCount after three adds", 3, album.trackCount());
        check("totalSeconds after three adds", 455, album.totalSeconds());
        Track longest = album.longestTrack();
        check("longestTrack finds Anthem", "Anthem", longest == null ? null : longest.getTitle());
        check("longestTrack returns the Track object", "Anthem (245s)", String.valueOf(longest));
        album.add(new Track("Encore", 245));
        Track tied = album.longestTrack();
        check("a tie keeps the track added first", "Anthem", tied == null ? null : tied.getTitle());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

